for k,checks in CHECKS.items():
    out[k]={}
    for tok,_ in checks:
        fs=res.get(str(k),{}).get(tok,[])
        out[k][tok]={"n":len(fs),"files":fs[:6]}
open(r"C:\Users\Administrator\.dsh\cache\memory-audit\targeted_out.json","w",encoding="utf-8").write(json.dumps(out,ensure_ascii=False,indent=1))
